// lib/veap.ts (auto-registered in lib/plugins.gen.ts)
import { Application } from "@veap/kernel";
import blogPlugin from "@veap/blog-plugin";

export const app = Application.configure()
  .withDatabase()
  .withPlugins([blogPlugin])
  .create();

// Querying blog posts in components or server actions:
import { BlogPost } from "@veap/blog-plugin";

const posts = await BlogPost.query()
  .where("status", "published")
  .with(["category", "tags", "comments"])
  .orderBy("published_at", "desc")
  .get();

// lib/veap.ts
import { Application } from "@veap/kernel";
import authPlugin from "@veap/auth-plugin";

export const app = Application.configure()
  .withDatabase()
  .withAuth()
  .withPlugins([authPlugin])
  .create();

// Verifying authentication in server components, layouts, or actions:
import { getCurrentSession } from "@veap/auth/server";
import { redirect } from "next/navigation";

const { session, user } = await getCurrentSession();
if (!session || !user) {
  redirect("/signin");
}

