import { Application } from "@veap/kernel";
import rbacPlugin from "@veap/rbac-plugin";

export const app = Application.configure()
  .withAuth()
  .withPlugins([rbacPlugin])
  .create();

// Checking security and roles in actions or server components:
import { checkSecurity, getCurrentSession } from "@veap/auth/server";

const { session, user } = await getCurrentSession();
const auth = await checkSecurity(session, user, ["admin"], ["post:update"]);
if (!auth.satisfied) {
  throw new Error("Forbidden: insufficient permissions");
}

