// models/Article.ts
import { Model } from "@veap/database";
import { Categorizable } from "@veap/categorizable";

export class Article extends Categorizable(Model) {
  static table = "articles";
}

// Querying with category scopes:
const articles = await Article.query()
  .whereCategory("technology")
  .withCategories()
  .get();

// models/Post.ts
import { Model } from "@veap/database";
import { Commentable } from "@veap/commentable";

export class Post extends Commentable(Model) {
  static table = "posts";
}

// Adding and querying comments:
const post = await Post.find("post-uuid");
await post.addComment({
  content: "Excellent article!",
  authorName: "Alice",
  status: "approved"
});

// models/Product.ts
import { Model } from "@veap/database";
import { Taggable } from "@veap/taggable";

export class Product extends Taggable(Model) {
  static table = "products";
}

// Attaching tags and querying:
const product = await Product.find("product-uuid");
await product.syncTags(["nextjs", "framework", "typescript"]);

const taggedProducts = await Product.query()
  .whereTag("nextjs")
  .withTags()
  .get();

// models/Page.ts
import { TranslatableModel } from "@veap/translatable";

export class Page extends TranslatableModel {
  static table = "pages";
  static translatable = ["title", "content", "meta_description"];
}

// Storing and retrieving translations:
const page = await Page.find("page-uuid");
page.setTranslation("title", "es", "Página Principal");
page.setTranslation("title", "en", "Home Page");
await page.save();
